def rename_with_suffix(names, suffix):
    result = []
    rename_map = {}
    for n in names:
        i = n.rfind('.')
        if i > 0:
            new = n[:i] + suffix + n[i:]
        else:
            new = n + suffix
        result.append(new)
        rename_map[n] = new
    return result
